    @name = N'MS_Description',
    @value = N'The watermark / last-modified value observed for THIS record on the last sync (per-record, independent of the entity-map-level CompanyIntegrationSyncWatermark).',
    @level0type = N'SCHEMA', @level0name = 're_members_ams',
    @level1type = N'TABLE', @level1name = 'Tasks',
    @level2type = N'COLUMN', @level2name = '__mj_integration_LastSeenModifiedValue';

IF NOT EXISTS (SELECT 1 FROM sys.fn_listextendedproperty(N'MS_Description', N'SCHEMA', N're_members_ams', N'TABLE', N'Tasks', N'COLUMN', N'__mj_integration_LastReconciledAt'))
EXEC sp_addextendedproperty
    @name = N'MS_Description',
    @value = N'Timestamp this record was last confirmed against the source system. Lets a reconcile find records not seen recently (delete-detection candidates).',
    @level0type = N'SCHEMA', @level0name = 're_members_ams',
    @level1type = N'TABLE', @level1name = 'Tasks',
    @level2type = N'COLUMN', @level2name = '__mj_integration_LastReconciledAt';

IF NOT EXISTS (SELECT 1 FROM sys.fn_listextendedproperty(N'MS_Description', N'SCHEMA', N're_members_ams', N'TABLE', N'Tasks', N'COLUMN', N'__mj_integration_LastWriterDirection'))
EXEC sp_addextendedproperty
    @name = N'MS_Description',
    @value = N'Which side last wrote this row: "Pull" (external→MJ) or "Push" (MJ→external). Informs conflict handling and audit.',
    @level0type = N'SCHEMA', @level0name = 're_members_ams',
    @level1type = N'TABLE', @level1name = 'Tasks',
    @level2type = N'COLUMN', @level2name = '__mj_integration_LastWriterDirection';

IF NOT EXISTS (SELECT 1 FROM sys.fn_listextendedproperty(N'MS_Description', N'SCHEMA', N're_members_ams', N'TABLE', N'Tasks', N'COLUMN', N'__mj_integration_IsTombstoned'))
EXEC sp_addextendedproperty
    @name = N'MS_Description',
    @value = N'Explicit soft-delete flag, set when the record is detected as deleted/archived upstream. A queryable tombstone, distinct from the SyncStatus="Archived" text status.',
    @level0type = N'SCHEMA', @level0name = 're_members_ams',
    @level1type = N'TABLE', @level1name = 'Tasks',
    @level2type = N'COLUMN', @level2name = '__mj_integration_IsTombstoned';

IF NOT EXISTS (SELECT 1 FROM sys.fn_listextendedproperty(N'MS_Description', N'SCHEMA', N're_members_ams', N'TABLE', N'Tasks', N'COLUMN', N'__mj_integration_DeletedDetectedAt'))
EXEC sp_addextendedproperty
    @name = N'MS_Description',
    @value = N'Timestamp the upstream deletion was detected (set alongside IsTombstoned). Null while the record is live.',
    @level0type = N'SCHEMA', @level0name = 're_members_ams',
    @level1type = N'TABLE', @level1name = 'Tasks',
    @level2type = N'COLUMN', @level2name = '__mj_integration_DeletedDetectedAt';

